mapper.select:
select v.id, v.product_id, v.product_key, v.version, cast(v.metadata_snapshot as varchar) as metadata_snapshot, v.change_type, v.change_description, v.operator, v.create_time, p.name as product_name from iot_product_metadata_version v left join iot_product p on v.product_id = p.id
and v.product_id = #{productId} and v.product_key = #{productKey} and v.change_type = #{changeType} and v.operator = #{operator}
order by v.version desc

select coalesce(max(version), 0)
from iot_product_metadata_version
where product_id = #{productId}


where product_id = #{productId}
order by version desc
limit 2

select count(*)
from iot_product_metadata_version
where product_id = #{productId}
